using System;
using System.Net;
using System.Net.Sockets;
using System.Threading;
using System.Threading.Tasks;

static async Task ServeAsync(CancellationToken ct)
{
    using var listener = new Socket(
        AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
    listener.Bind(new IPEndPoint(IPAddress.Loopback, 41000));
    listener.Listen(backlog: 32);
    Console.WriteLine($"LISTEN local={listener.LocalEndPoint}");

    while (true)
    {
        Socket connection = await listener.AcceptAsync(ct);
        await HandleOneAsync(connection, ct); // 所有權交給 handler；未捕捉例外會停止此服務迴圈
        // handler 結束並釋放 connection 後，listener 再接受下一筆
    }
}

static async Task HandleOneAsync(Socket connection, CancellationToken ct)
{
    using (connection)
    using (var stream = new NetworkStream(connection, ownsSocket: false))
    {
        Console.WriteLine(
            $"ACCEPT local={connection.LocalEndPoint} remote={connection.RemoteEndPoint}");
        byte[] oneByteRequest = new byte[1]; // 教學回音契約：請求固定為 1 byte
        int n = await stream.ReadAsync(oneByteRequest.AsMemory(), ct);
        if (n == 1)
            await stream.WriteAsync(oneByteRequest.AsMemory(0, n), ct);
    }
}

while (true)
{
    using Socket connection = await listener.AcceptAsync(ct);
    _ = HandleOneAsync(connection, ct); // 沒有等待；scope 結束就 Dispose
}
